  ('zh-CN', 'memory.title', $json$"JayV 对这个项目的了解"$json$::jsonb),
  ('zh-CN', 'memory.description', $json$"笔记在会话开始时发给智能体一次。配方只随与之相似的请求一起发送。所有内容都会与你的账户同步。"$json$::jsonb),
  ('zh-CN', 'memory.tab.notes', $json$"笔记"$json$::jsonb),
  ('zh-CN', 'memory.tab.recipes', $json$"配方"$json$::jsonb),
  ('zh-CN', 'memory.notes.hint', $json$"智能体原本需要探索才能找到的简短事实：如何测试、东西放在哪里、什么不要动。当门卫询问某样东西在哪里或如何检查时，你的回答也会保存在这里。"$json$::jsonb),
  ('zh-CN', 'memory.notes.used', $json$"{used} / {limit} 个字符"$json$::jsonb),
