  ('hi', 'memory.description', $json$"नोट्स सत्र शुरू होने पर एक बार एजेंट को जाते हैं। रेसिपी सिर्फ़ उनसे मिलते-जुलते अनुरोधों के साथ जाती हैं। सब कुछ आपके खाते के साथ सिंक होता है।"$json$::jsonb),
