  ('hi', 'memory.notes.hint', $json$"छोटे तथ्य जिन्हें एजेंट को वरना खोजना पड़ता: कैसे टेस्ट करें, चीज़ें कहाँ हैं, किसे न छुएँ। जब द्वारपाल पूछता है कि कुछ कहाँ है या कैसे जाँचें, तो आपका जवाब भी यहीं सहेजा जाता है।"$json$::jsonb),
