  ('hi', 'expertise.suggestion', $json$"पिछले {days} दिनों में आपके {checks} अनुरोधों में से {passed} पहली बार में द्वारपाल से निकल गए। {level} स्तर इस इतिहास से बेहतर मेल खाता है।"$json$::jsonb),
  ('hi', 'expertise.suggestion.apply', $json$"{level} पर जाएँ"$json$::jsonb),
  ('hi', 'usage.jev.work.noteLearned', $json$"सीखे गए नोट्स"$json$::jsonb),
  ('hi', 'usage.jev.work.answerRecalled', $json$"दोबारा इस्तेमाल हुए पुराने उत्तर"$json$::jsonb),
  ('hi', 'whatsNew.item.projectNotes.title', $json$"प्रोजेक्ट मेमोरी"$json$::jsonb),
  ('hi', 'whatsNew.item.projectNotes.detail', $json$"किसी प्रोजेक्ट की चैट स्क्रीन पर, प्रोजेक्ट मेमोरी बटन छोटे नोट्स रखता है (अधिकतम 2,200 वर्ण): कैसे टेस्ट करें, चीज़ें कहाँ हैं, किसे न छुएँ। ये सत्र शुरू होने पर एक बार एजेंट को जाते हैं और उसे इन्हें फिर से खोजने के लिए प्रोजेक्ट छानने से बचाते हैं। गोपनीय जानकारी अस्वीकार होती है, और सब कुछ आपके खाते से सिंक होता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.gateLearning.title', $json$"द्वारपाल आपके जवाबों से सीखता है"$json$::jsonb),
  ('hi', 'whatsNew.item.gateLearning.detail', $json$"जब द्वारपाल पूछता है कि कुछ कहाँ है या बदलाव कैसे जाँचें, और आप अगले अनुरोध में जवाब देते हैं, तो जवाब वाला वाक्य प्रोजेक्ट नोट बन जाता है। उसके बाद द्वारपाल उस प्रोजेक्ट में यह दोबारा नहीं पूछता, और एजेंट को जवाब पहले से मिल जाता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.routingFeedback.title', $json$"रूटिंग नाकाम रहे काम से सीखती है"$json$::jsonb),
  ('hi', 'whatsNew.item.routingFeedback.detail', $json$"पूरा आया उत्तर अब हमेशा सफलता नहीं गिना जाता। अगर आपका अगला संदेश कहता है कि यह काम नहीं किया, या निकास द्वार उत्तर रोक लेता है, तो जवाब देने वाला मॉडल अंक खोता है। हर मॉडल का स्कोर अब अनुरोध के प्रकार के हिसाब से भी रखा जाता है, इसलिए समीक्षा और टेस्ट अलग-अलग मॉडलों को जा सकते हैं।"$json$::jsonb),
  ('hi', 'whatsNew.item.levelSuggestion.title', $json$"स्तर का सुझाव"$json$::jsonb),
  ('hi', 'whatsNew.item.levelSuggestion.detail', $json$"सेटिंग्स में, आपका स्तर अब पिछले 30 दिनों का द्वारपाल इतिहास कहे तो (20 अनुरोधों से) एक कदम ऊपर या नीचे जाने का सुझाव देता है: लगभग सब कुछ पहली बार में निकल रहा हो, या बहुत से अनुरोध रोके जा रहे हों। बदलाव अब भी आपका है, एक क्लिक में।"$json$::jsonb),
  ('hi', 'whatsNew.item.chatSearch.title', $json$"चैट में खोज"$json$::jsonb),
  ('hi', 'whatsNew.item.chatSearch.detail', $json$"प्रोजेक्ट की चैट स्क्रीन में अब बातचीत में कही गई बातों की खोज है, जिसमें मिला हुआ हिस्सा हाइलाइट होता है। यह आपके कंप्यूटर पर, एक स्थानीय इंडेक्स पर, बिना नेटवर्क के चलती है।"$json$::jsonb),
  ('hi', 'whatsNew.item.answerRecall.title', $json$"प्रोजेक्ट के मौजूदा उत्तरों का दोबारा इस्तेमाल"$json$::jsonb),
  ('hi', 'whatsNew.item.answerRecall.detail', $json$"जब कोई अनुरोध उसी प्रोजेक्ट की किसी दूसरी चैट में पहले से जवाब दिए गए अनुरोध जैसा ही होता है, तो पिछला उत्तर छोटा करके साथ जाता है, और एजेंट सब कुछ दोबारा खोजने और जवाब देने के बजाय उससे शुरू करता है। हर बार ऐसा होने पर यह Jev पैनल में दिखता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.recipes.title', $json$"दोहराए जाने वाले अनुरोधों के लिए रेसिपी"$json$::jsonb),
  ('hi', 'whatsNew.item.recipes.detail', $json$"प्रोजेक्ट मेमोरी उन अनुरोधों को दिखाती है जो आप तीन या अधिक बार कर चुके हैं, और उन्हें रेसिपी बनाने देती है: उस तरह के अनुरोध के लिए आपकी प्रक्रिया। रेसिपी सिर्फ़ तब साथ जाती है जब अनुरोध उससे मिलता हो, इसलिए बाकी अनुरोधों पर बोझ नहीं डालती।"$json$::jsonb),
  ('ar', 'memory.open', $json$"ذاكرة المشروع"$json$::jsonb),
  ('ar', 'memory.eyebrow', $json$"ذاكرة المشروع"$json$::jsonb),
  ('ar', 'memory.title', $json$"ما يعرفه JayV عن هذا المشروع"$json$::jsonb),
  ('ar', 'memory.description', $json$"تُرسل الملاحظات إلى الوكيل مرة واحدة عند بدء الجلسة. أما الوصفات فتُرسل فقط مع الطلبات المشابهة لها. كل شيء يُزامَن مع حسابك."$json$::jsonb),
  ('ar', 'memory.tab.notes', $json$"الملاحظات"$json$::jsonb),
  ('ar', 'memory.tab.recipes', $json$"الوصفات"$json$::jsonb),
  ('ar', 'memory.notes.hint', $json$"حقائق قصيرة كان على الوكيل أن يستكشف ليعرفها: كيف تختبر، وأين توجد الأشياء، وما الذي لا يجب لمسه. وما تجيب به عندما تسأل البوابة عن مكان شيء أو كيفية التحقق منه يُحفظ هنا أيضًا."$json$::jsonb),
  ('ar', 'memory.notes.used', $json$"{used} / {limit} حرفًا"$json$::jsonb),
