  ('fr', 'memory.description', $json$"Les notes vont à l’agent une fois, au début d’une session. Les recettes n’accompagnent que les demandes qui leur ressemblent. Tout se synchronise avec votre compte."$json$::jsonb),
  ('fr', 'memory.tab.notes', $json$"Notes"$json$::jsonb),
  ('fr', 'memory.tab.recipes', $json$"Recettes"$json$::jsonb),
  ('fr', 'memory.notes.hint', $json$"Des faits courts que l’agent devrait sinon explorer pour trouver : comment tester, où se trouvent les choses, à quoi ne pas toucher. Ce que vous répondez quand le contrôle demande où se trouve quelque chose ou comment le vérifier est aussi enregistré ici."$json$::jsonb),
  ('fr', 'memory.notes.used', $json$"{used} / {limit} caractères"$json$::jsonb),
