  ('fr', 'memory.edit', $json$"Modifier"$json$::jsonb),
  ('fr', 'memory.recipes.hint', $json$"Une recette est votre procédure pour une demande que vous répétez, jusqu’à {limit} caractères. Elle n’accompagne la demande que si celle-ci ressemble à son déclencheur."$json$::jsonb),
