  ('fr', 'memory.full', $json$"Les notes du projet sont pleines ({limit} caractères). Raccourcissez ou supprimez d’abord une note."$json$::jsonb),
  ('fr', 'memory.missing', $json$"Cette note n’existe plus."$json$::jsonb),
