  ('ru', 'memory.note.add', $json$"Добавить заметку"$json$::jsonb),
  ('ru', 'memory.note.learned', $json$"Выучено у контроля"$json$::jsonb),
  ('ru', 'memory.save', $json$"Сохранить"$json$::jsonb),
  ('ru', 'memory.edit', $json$"Изменить"$json$::jsonb),
  ('ru', 'memory.recipes.hint', $json$"Рецепт — это ваш порядок действий для повторяющегося запроса, до {limit} символов. Он отправляется, только когда запрос похож на его триггер."$json$::jsonb),
  ('ru', 'memory.recipes.empty', $json$"Рецептов пока нет."$json$::jsonb),
  ('ru', 'memory.repeated', $json$"Повторяющиеся запросы"$json$::jsonb),
  ('ru', 'memory.repeated.count', $json$"{count}×"$json$::jsonb),
