  ('ru', 'memory.recipe.name.placeholder', $json$"напр.: Новая миграция"$json$::jsonb),
  ('ru', 'memory.recipe.trigger', $json$"Запрос-триггер"$json$::jsonb),
  ('ru', 'memory.recipe.trigger.placeholder', $json$"Запрос, на который отвечает этот рецепт (если пусто, берётся название)"$json$::jsonb),
  ('ru', 'memory.recipe.steps', $json$"Шаги"$json$::jsonb),
  ('ru', 'memory.recipe.steps.placeholder', $json$"напр.: 1. Создайте файл в migrations/ 2. Запустите тесты миграций"$json$::jsonb),
  ('ru', 'memory.recipe.add', $json$"Добавить рецепт"$json$::jsonb),
