  ('ru', 'memory.empty', $json$"Сначала что-нибудь напишите."$json$::jsonb),
  ('ru', 'memory.secret', $json$"Похоже на секрет (ключ, токен или пароль). Заметки уходят агенту, поэтому хранить в них секреты нельзя."$json$::jsonb),
  ('ru', 'memory.recipe.untitled', $json$"Дайте рецепту название."$json$::jsonb),
