  ('ja', 'memory.recipe.trigger', $json$"トリガーとなるリクエスト"$json$::jsonb),
  ('ja', 'memory.recipe.trigger.placeholder', $json$"このレシピが対応するリクエスト（空なら名前を使用）"$json$::jsonb),
  ('ja', 'memory.recipe.steps', $json$"手順"$json$::jsonb),
  ('ja', 'memory.recipe.steps.placeholder', $json$"例：1. migrations/ にファイルを作成 2. マイグレーションのテストを実行"$json$::jsonb),
  ('ja', 'memory.recipe.add', $json$"レシピを追加"$json$::jsonb),
