-- v0.35.0: o JayV aprende com o uso.
--
-- A memória do projeto: notas curtas que o agente lê uma vez, quando a sessão
-- começa, e receitas (o passo a passo de quem usa para um tipo de pedido) que
-- vão só junto dos pedidos parecidos. As notas escritas pela pessoa têm
-- `source = 'manual'`; as que o app aprende das respostas às perguntas da
-- portaria têm `source = 'gate'` e `covers` com o critério que elas cobrem
-- (`says_where`, `says_when_done`), para a portaria não perguntar de novo.
--
-- Como as outras tabelas sincronizadas, cada linha é de um usuário
-- (`user_id`), nunca é apagada de verdade (`row_deleted_at`) e sobe e desce
-- pelo `sync_row`. A nota não é compartilhada com a organização.
--
-- Apagar o projeto apaga as notas dele: `cascade_row_deletion` ganha a aresta
-- projects → project_notes, e a nota que chega com o projeto já apagado nasce
-- apagada.
--
-- E os textos: a janela da memória, a busca nos chats, a sugestão de nível,
-- duas linhas novas no painel do Jev e os itens da janela "Novidades".

create table public.project_notes (
  id text primary key,
  project_id text not null references public.projects(id) on delete cascade,
  kind text not null check (kind in ('note', 'recipe')),
  title text not null default '',
  body text not null,
  trigger text not null default '',
  covers text not null default '',
  source text not null default 'manual' check (source in ('manual', 'gate', 'repeat')),
  created_at text not null,
  updated_at text not null,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  row_updated_at timestamptz not null default now(),
  row_deleted_at timestamptz,
  synced_at timestamptz not null default clock_timestamp()
);

create index project_notes_user_synced on public.project_notes (user_id, synced_at);
create trigger sync_row before insert or update on public.project_notes
  for each row execute function public.sync_row();

alter table public.project_notes enable row level security;
create policy "dono lê" on public.project_notes for select to authenticated using (user_id = (select auth.uid()));
create policy "dono escreve" on public.project_notes for insert to authenticated with check (user_id = (select auth.uid()));
create policy "dono muda" on public.project_notes for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "segundo fator" on public.project_notes as restrictive to authenticated
  using ((select public.second_factor_ok())) with check ((select public.second_factor_ok()));
revoke delete, truncate on public.project_notes from anon, authenticated;
revoke all on public.project_notes from anon;

-- A mesma função de antes, com a aresta nova.
create or replace function public.cascade_row_deletion() returns trigger
language plpgsql
set search_path = ''
as $$
declare
  child record;
begin
  for child in
    select * from (values
      ('projects', 'chats', 'project_id'),
      ('projects', 'project_notes', 'project_id'),
      ('chats', 'turns', 'chat_id'),
      ('chats', 'messages', 'chat_id'),
      ('turns', 'entry_checks', 'turn_id'),
      ('turns', 'exit_checks', 'turn_id'),
      ('turns', 'turn_events', 'turn_id'),
      ('turns', 'questions', 'turn_id')
    ) as edges(parent, name, fk)
    where parent = tg_table_name
  loop
    -- `row_updated_at` nunca recua: o `sync_row` descartaria a marca como
    -- escrita atrasada.
    execute format(
      'update public.%I set row_deleted_at = $1, row_updated_at = greatest(row_updated_at, $1)
        where %I = $2 and row_deleted_at is null',
      child.name, child.fk)
    using new.row_deleted_at, new.id;
  end loop;
  return null;
end
$$;

-- Antes de `sync_row` pela ordem do nome, como nas outras tabelas filhas.
create trigger inherit_row_deletion before insert or update on public.project_notes
  for each row execute function public.inherit_row_deletion('projects', 'project_id');

on conflict (locale, key) do update set value = excluded.value;
